/bin/bash -lc "python3 -c 'import plan_review
for rel,data in plan_review._LEGACY_ASSETS.items():
    raw=plan_review._decode_asset(data).decode(\"utf-8\",errors=\"replace\")
    sub=plan_review.legacy_asset_bytes(rel).decode(\"utf-8\",errors=\"replace\")
    if \"larch_quiet_init\" in raw or \"larch_quiet_init\" in sub or \"validate-design-tmpdir\" in raw or \"validate-design-tmpdir\" in sub:
        print(\"===\",rel)
        for label,body in [(\"raw\",raw),(\"sub\",sub)]:
            print(\"---\",label)
            lines=body.splitlines()
            for i,line in enumerate(lines,1):
                if \"larch_quiet_init\" in line or \"validate-design-tmpdir\" in line or (\"larch_quiet\" in line) or (\"DESIGN_TMPDIR\" in line and i < 180):
                    print(f\"{i:4}: {line}\")
        print()'"

